<script setup>
import ManagementPage from '../../../Components/Inventory/ManagementPage.vue';
import { computed, reactive, ref } from 'vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import PageHeader from '../../../Components/Ui/PageHeader.vue';
import StatRail from '../../../Components/Ui/StatRail.vue';
import EmptyState from '../../../Components/Ui/EmptyState.vue';
import EmployeeSheet from '../../../Components/StaffMeals/EmployeeSheet.vue';
import { useConfirm } from '../../../Composables/useConfirm';

defineOptions({layout:AdminLayout});
const props=defineProps({month:{type:Object,required:true},rows:{type:Array,default:()=>[]},totals:{type:Object,required:true},branches:{type:Array,default:()=>[]},selectedBranchId:[Number,String,null],can:{type:Object,required:true},urls:{type:Object,required:true},employeeForm:{type:Object,default:()=>({})}});
const closeOpen=ref(false);const {ask}=useConfirm();const monthFilter=ref(props.month.value);
const employeeOpen=ref(false);
const closeForm=useForm({month:props.month.value,method:'payroll_deduction',notes:'',branch_id:props.selectedBranchId??''});
const overRows=computed(()=>props.rows.filter(row=>row.overflowValue>0||row.hardOver));
const accountingOpen=ref(false);
function changeMonth(){router.get(props.urls.index,{month:monthFilter.value},{preserveState:false})}
async function closeMonth(){const branch=props.branches.find(b=>String(b.id)===String(closeForm.branch_id));const yes=await ask({title:`إقفال ${closeForm.month}؟`,message:`سيتم تسوية الحركات المفتوحة${branch?' لفرع '+branch.name:''} بالطريقة المختارة وإنشاء كشف ثابت للطباعة.`,confirmLabel:'إقفال وتوليد الكشف'});if(yes)closeForm.post(props.urls.closeMonth)}
const progressTone=row=>row.hardOver||Number(row.usagePct)>=120?'danger':Number(row.usagePct)>=100?'warning':Number(row.usagePct)>=80?'info':'success';
</script>
<template>
    <ManagementPage mode="records">
<Head title="بدل وجبات الموظفين"/>
<PageHeader title="بدل وجبات الموظفين" icon="bi-cup-hot-fill" :subtitle="`متابعة ${month.label} دون اشتراط حساب دخول للعامل`"><template #actions><Link :href="urls.closures" class="btn btn-light"><i class="bi bi-archive"></i> الإقفالات</Link><button v-if="can.manageEmployees" type="button" class="btn btn-light" @click="employeeOpen=true"><i class="bi bi-person-plus"></i> موظف جديد</button><button v-if="can.closeMonth" class="btn btn-outline-success" type="button" @click="closeOpen=true"><i class="bi bi-calendar-check"></i> إقفال الشهر</button><Link v-if="can.quickConsume" :href="urls.quickConsume" class="btn btn-primary"><i class="bi bi-plus-lg"></i> تسجيل استهلاك</Link></template></PageHeader>
<section class="month-bar"><div><small>الفترة المعروضة</small><strong>{{month.label}}</strong></div><label><span>غيّر الشهر</span><input v-model="monthFilter" type="month" @change="changeMonth"></label><button type="button" @click="accountingOpen=!accountingOpen"><i class="bi bi-journal-check"></i> كيف تُسجّل محاسبياً؟ <i class="bi" :class="accountingOpen?'bi-chevron-up':'bi-chevron-down'"></i></button></section>
<section v-if="accountingOpen" class="accounting"><article><b>الجزء ضمن البدل</b><span>عند صرف المكونات: من ح/ تكلفة وجبات الموظفين إلى ح/ المخزون بالتكلفة الفعلية.</span></article><article><b>الجزء المتجاوز</b><span>وحده يصبح مستحقاً على الموظف ويُحصّل نقداً فعلياً أو بخصم راتب منفذ.</span></article><article><b>هدية أو إعفاء</b><span>لا ينشئ ديناً جديداً؛ والتكلفة الفعلية تبقى ظاهرة كمصروف منفعة موظف.</span></article></section>
<StatRail :stats="[{label:'موظفون لهم بدل',value:totals.staffCount,icon:'bi-people-fill',color:'primary'},{label:'حدود الشهر',value:totals.allowance,icon:'bi-speedometer2',color:'muted'},{label:'قيمة الوجبات',value:totals.used,icon:'bi-cup-straw',color:'accent'},{label:'تحمله المطعم',value:totals.covered,icon:'bi-shield-check',color:'success'},{label:'مستحق على الموظفين',value:totals.outstanding,icon:'bi-wallet2',color:'warning'}]"/>
<section v-if="overRows.length" class="attention"><i class="bi bi-exclamation-triangle-fill"></i><div><strong>{{overRows.length}} موظفاً يحتاجون مراجعة</strong><small>تجاوز بدل الشهر أو سقف الدين؛ افتح تفاصيل الموظف قبل التسوية.</small></div><div><a v-for="row in overRows.slice(0,3)" :key="row.id" :href="row.showUrl">{{row.name}}</a></div></section>
<section class="staff-panel"><header><div><small>سجل الموظفين</small><h2>{{rows.length}} موظفاً</h2></div><span class="legend"><i></i> الاستخدام من الحد الشهري</span></header><div v-if="rows.length" class="staff-list"><article v-for="row in rows" :key="row.id" :class="[{over:row.overflowValue>0,hard:row.hardOver}]"><div class="person"><span>{{row.name.trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('')}}</span><div><strong>{{row.name}}</strong><small>{{row.role}} · {{row.access}}</small></div></div><div class="usage"><div><span>استهلاك الشهر</span><b>{{row.used}}</b></div><div class="progress"><i :class="`is-${progressTone(row)}`" :style="{width:`${Math.min(100,Number(row.usagePct||0))}%`}"></i></div><small v-if="row.usagePct!==null">{{row.usagePct}}% من {{row.allowance}}</small><small v-else>لا يوجد حد شهري</small></div><div class="numbers"><span><small>المستحق</small><b>{{row.outstanding}}</b></span><span v-if="row.ceiling"><small>المتاح حتى السقف</small><b :class="{danger:row.hardOver}">{{row.hardOver?'متجاوز':row.ceilingHeadroom}}</b></span><span v-if="row.giftedValue"><small>هدايا</small><b class="gift">{{row.gifted}}</b></span></div><Link :href="row.showUrl" class="open"><span>تفاصيل وتسوية</span><i class="bi bi-chevron-left"></i></Link></article></div><EmptyState v-else icon="bi-person-plus" title="ابدأ بإضافة الموظفين" message="أضف العامل باسمه فقط؛ حساب الدخول اختياري تماماً."><template #cta><button v-if="can.manageEmployees" type="button" class="btn btn-primary" @click="employeeOpen=true">إضافة أول موظف</button></template></EmptyState></section>
<EmployeeSheet :open="employeeOpen" :store-url="urls.employeesStore" :options="employeeForm" @close="employeeOpen=false" />
<Teleport to="body"><Transition name="fade"><div v-if="closeOpen" class="backdrop" @click.self="closeOpen=false"><form class="close-card" @submit.prevent="closeMonth"><header><div><small>إجراء مالي شهري</small><h2>إقفال مستحقات الوجبات</h2></div><button type="button" @click="closeOpen=false"><i class="bi bi-x-lg"></i></button></header><p>يشمل فقط الجزء المتجاوز من البدل. التحصيل النقدي يتم منفرداً وقت استلام المال، ولا يُفترض تلقائياً ضمن الإقفال.</p><label><span>الشهر *</span><input v-model="closeForm.month" type="month" required></label><label v-if="branches.length"><span>الفرع *</span><select v-model="closeForm.branch_id" required><option value="">اختر الفرع</option><option v-for="branch in branches" :key="branch.id" :value="branch.id">{{branch.name}}</option></select><small>الإقفال مستقل لكل فرع حفاظاً على الفصل المالي.</small></label><label><span>طريقة التسوية *</span><select v-model="closeForm.method" required><option value="payroll_deduction">خصم منفذ من الراتب</option><option value="writeoff">شطب إداري</option></select></label><label><span>ملاحظة</span><textarea v-model="closeForm.notes" rows="2" maxlength="1000" placeholder="مثال: خصم راتب شهر آب"></textarea></label><footer><button type="button" class="btn btn-light" @click="closeOpen=false">تراجع</button><button class="btn btn-primary" :disabled="closeForm.processing"><i class="bi bi-check2-circle"></i> إقفال وتوليد الكشف</button></footer></form></div></Transition></Teleport>
    </ManagementPage>
</template>
<style scoped>
