 header{display:flex;justify-content:space-between}.close-card h2,.close-card small{margin:0}.close-card h2{font-size:1rem}.close-card small{font-size:.875rem;color:var(--muted, #626B6D)}.close-card header button{border:0;background:var(--canvas, #F7F3ED);border-radius:9px;width:36px;height:36px}.close-card>p{font-size:.875rem;color:var(--muted, #626B6D);background:var(--canvas, #F7F3ED);padding:.65rem;border-radius:9px}.close-card label{display:grid;gap:.3rem}.close-card label>span{font-size:.875rem;font-weight:800}.close-card input,.close-card select,.close-card textarea{border:1px solid var(--brand-soft, #F3E3D8);border-radius:10px;padding:.55rem;background:var(--surface, #FFFDFA)}.close-card label small{color:var(--ink, #25343A)}.close-card footer{display:flex;justify-content:flex-end;gap:.5rem;padding-top:.3rem}.fade-enter-active,.fade-leave-active{transition:.18s}.fade-enter-from,.fade-leave-to{opacity:0}@media(max-width:1000px){.staff-list article{grid-template-columns:1fr 1.2fr 110px}.numbers{display:none}.accounting{grid-template-columns:1fr}.attention>div:last-child{display:none}}@media(max-width:650px){.month-bar{flex-wrap:wrap}.month-bar>div{width:100%}.month-bar label,.month-bar>button{flex:1}.staff-list article{grid-template-columns:1fr auto}.usage{grid-column:1/-1;grid-row:2}.open{grid-column:2;grid-row:1}.open span{display:none}.staff-panel,.month-bar{border-radius:12px}}

