.month-bar { padding: 18px 20px; margin-bottom: 20px; border-radius: 12px; } .staff-panel { border-radius: 12px; margin-top: 20px; } .staff-panel > header { padding: 20px; background: var(--canvas); } .staff-list .person { padding: 18px 20px; min-height: 84px; } .close-card { padding: 24px; border-radius: 12px; }
